/// <summary>
/// MPJ_2864_CreditLimitBalance 03/11/2021
/// Service class to run the update and creation of new record
/// </summary>
public class METPopulateCustCreditLimitService extends SysOperationServiceBase
{
    
}

Method.Source:
    /// <summary>
    /// MPJ_2864_CreditLimitBalance 03/11/2021
    /// Checks if run in batch or not.
    /// </summary>
    /// <param name = "_dataContract">Data contract</param>
    public void processOperation(METPopulateCustCreditLimitContract _dataContract)
    {
        BatchHeader                             batchHeader;
        SysOperationServiceController           controller;
        METPopulateCustCreditLimitContract      dataContract;
        Query                                   q;
        QueryBuildDataSource                    qbds;
        QueryRun                                queryRun;
        CustTable                               custTable;
        int                                     totalCount, bundleSize, i, j;
        CustAccount                             fromCustomer,toCustomer;
        List                                    custAccounts;
        

        totalCount = this.custRecordCount();
        bundleSize = real2int(roundUp((totalCount / _dataContract.getNumOfTasks()), 1.0));

        q          = new Query();
        qbds       = q.addDataSource(TableNum(CustTable));
        queryRun   = new QueryRun(q);

        custAccounts = new List(Types::String);

        try
        {
            if (this.isExecutingInBatch())
            {
                while (queryRun.next())
                {
                    custTable = queryRun.get(tablenum(CustTable), 1);
                    
                    if (custTable)
                    {
                        i++;
                        j++;
                        custAccounts.addEnd(custTable.AccountNum);

                        if (i == 1)
                        {
                            fromCustomer = custTable.AccountNum;
                        }
                        
                        if (i >= bundleSize || j == totalCount)
                        {
                            toCustomer = custTable.AccountNum;

                            if (!batchHeader)
                            {
                                batchHeader = this.getCurrentBatchHeader();
                            }

                            // create new controller for the runtime task
                            controller = new SysOperationServiceController(classStr(METPopulateCustCreditLimitSubTaskService), methodStr(METPopulateCustCreditLimitSubTaskService, processSubTask));
                            controller.parmDialogCaption(strFmt("@MET:CustCreditLimitServiceSubTaskDesc", fromCustomer, toCustomer));

                            // grab contract instance from controller
                            dataContract = controller.getDataContractObject() as METPopulateCustCreditLimitContract;
                            dataContract.getCustAccountList(custAccounts);
                            dataContract.getNumOfTasks(_dataContract.getNumOfTasks());
                            
                            // create subTask according to controller instance and header recid
                            batchHeader.addRuntimeTask(controller, this.getCurrentBatchTask().RecId);

                            // Resets counts. int j is not reset due to spill over of recrods at the end
                            custAccounts = new List(Types::String);
                            i = 0;
                        }
                    }
                }
            }
            else
            {
                throw error ("@MET:BatchProcessingMustBeSelected");
            }

            if(batchHeader)
            {
                // save the batchheader if it has been created
                batchHeader.save();
            }
            
        }
        catch
        {
            info ("@MET:PopulateCustCreditErrorHandler");
        }

    }

    /// <summary>
    /// MPJ_2864_CreditLimitBalance 03/11/2021
    /// Gets total AmountMST (Balance)
    /// </summary>
    /// <param name = "_AccountNum">Cust account num</param>
    /// <returns>total amount mst</returns>
    public AmountMST getBalance(AccountNum _AccountNum)
    {
        CustTrans   custTrans;
        SalesTable  salesTable;

        select sum(AmountMST) from custTrans
            where custTrans.AccountNum == _AccountNum;

        select sum(Estimate) from salesTable
            where salesTable.custAccount == _AccountNum;

        return custTrans.AmountMST + salesTable.Estimate;
    }

    /// <summary>
    /// MPJ_2864_CreditLimitBalance - kscerri - 22/03/2021
    /// </summary>
    /// <returns>total row count</returns>
    public counter custRecordCount()
    {
        CustTable custTable;

        select count(RecId) from custTable;

        return int642int(custTable.RecId);
    }
